package expo.modules.recognitioncpu;

import android.content.Context;
import android.system.*;
import java.io.*;
import java.nio.channels.FileLock;
import java.util.*;

/** Fixed ledger and 64 bounded record roots only. No caller path or historical proof writer. */
public final class EnrollmentDisk implements EnrollmentStore.Disk,AutoCloseable {
 private final Map<String,Root> roots=new LinkedHashMap<>();private Root parentHandle;private String lockIdentity;private boolean closed;
 public final EnrollmentControl control; private final File parent,ledger;private final FileOutputStream lockStream;private final FileLock lock;private final EnrollmentProofInventory proofs;
 public EnrollmentDisk(Context c)throws Exception{
  parent=c.getFilesDir().getCanonicalFile();parentHandle=new Root(parent);FileOutputStream stream=null;FileLock held=null;
  try{proofs=new EnrollmentProofInventory(parent);ledger=new File(parent,"observed-enrollment-ledger-v1");directory(ledger,true);File f=new File(ledger,"owner.lock");
   try{Os.close(Os.open(f.getPath(),OsConstants.O_WRONLY|OsConstants.O_CREAT|OsConstants.O_EXCL|OsConstants.O_NOFOLLOW|OsConstants.O_NONBLOCK,0600));sync(ledger);}catch(ErrnoException e){if(e.errno!=OsConstants.EEXIST)throw e;}
   StructStat before=Os.lstat(f.getPath());regular(before,0);stream=new FileOutputStream(Os.open(f.getPath(),OsConstants.O_WRONLY|OsConstants.O_NOFOLLOW|OsConstants.O_NONBLOCK,0));ObservedEnrollment.require(identity(before).equals(identity(Os.fstat(stream.getFD()))),"LOCK_CHANGED");held=stream.getChannel().tryLock();ObservedEnrollment.require(held!=null,"ENROLLMENT_LOCKED");lockStream=stream;lock=held;lockIdentity=identity(before);guard();control=new EnrollmentControl(parent,new EnrollmentControl.Quota(){public void check(long logicalExtra,long physicalPending)throws Exception{EnrollmentReportBudget.write(used(),logicalExtra,free(),physicalPending);}public void physical(long pending){EnrollmentReportBudget.physical(free(),pending);}});
  }catch(Exception e){if(held!=null)try{held.release();}catch(Exception x){e.addSuppressed(x);}if(stream!=null)try{stream.close();}catch(Exception x){e.addSuppressed(x);}for(Root root:roots.values())try{root.close();}catch(Exception x){e.addSuppressed(x);}try{parentHandle.close();}catch(Exception x){e.addSuppressed(x);}throw e;}
 }
 static String identity(StructStat s){return s.st_dev+":"+s.st_ino+":"+s.st_mode+":"+s.st_uid+":"+s.st_nlink+":"+s.st_size+":"+s.st_mtim.tv_sec+":"+s.st_mtim.tv_nsec+":"+s.st_ctim.tv_sec+":"+s.st_ctim.tv_nsec;}
 static void regular(StructStat s,long max){EnrollmentIdentity.regular(OsConstants.S_ISREG(s.st_mode),s.st_uid,android.os.Process.myUid(),s.st_nlink,s.st_size,max);}
 private static final class Root implements AutoCloseable {
  final File file;final java.io.FileDescriptor fd;final String seal;
  static String key(StructStat s){return s.st_dev+":"+s.st_ino+":"+s.st_mode+":"+s.st_uid;}
  Root(File f)throws Exception{file=f;StructStat s=Os.lstat(f.getPath());ObservedEnrollment.require(f.equals(f.getCanonicalFile())&&OsConstants.S_ISDIR(s.st_mode)&&s.st_uid==android.os.Process.myUid(),"ROOT_IDENTITY");fd=Os.open(f.getPath(),OsConstants.O_RDONLY|OsConstants.O_NOFOLLOW|OsConstants.O_NONBLOCK,0);seal=key(s);try{verify();}catch(Exception e){Os.close(fd);throw e;}}
  void verify()throws Exception{ObservedEnrollment.require(file.equals(file.getCanonicalFile()),"ROOT_ALIAS");EnrollmentIdentity.directory(seal,key(Os.lstat(file.getPath())),key(Os.fstat(fd)));}
  public void close()throws Exception{Os.close(fd);}
 }
 private void guard()throws Exception{ObservedEnrollment.require(!closed&&lock.isValid(),"LOCK_CLOSED");parentHandle.verify();Root root=roots.get(ledger.getPath());root.verify();StructStat path=Os.lstat(new File(ledger,"owner.lock").getPath()),held=Os.fstat(lockStream.getFD());regular(path,0);regular(held,0);EnrollmentIdentity.file(lockIdentity,identity(path),identity(held));}
 private void directory(File dir,boolean create)throws Exception{parentHandle.verify();Root held=roots.get(dir.getPath());if(held!=null){held.verify();return;}try{Os.lstat(dir.getPath());}catch(ErrnoException e){if(e.errno!=OsConstants.ENOENT||!create)throw e;ObservedEnrollment.require(dir.mkdir(),"ROOT_CREATE");sync(parent);}roots.put(dir.getPath(),new Root(dir));parentHandle.verify();}
 static void sync(File dir)throws Exception{java.io.FileDescriptor fd=Os.open(dir.getPath(),OsConstants.O_RDONLY|OsConstants.O_NOFOLLOW,0);try{ObservedEnrollment.require(OsConstants.S_ISDIR(Os.fstat(fd).st_mode),"SYNC_DIRECTORY");Os.fsync(fd);}finally{Os.close(fd);}}
 private static int limit(String name,boolean meta){if(name.endsWith(".new"))name=name.substring(0,name.length()-4);if(meta){ObservedEnrollment.require(name.matches("event-[0-9]{4}")&&Integer.parseInt(name.substring(6))>=1&&Integer.parseInt(name.substring(6))<=4096,"EVENT_NAME");return EnrollmentStore.EVENT_BYTES;}switch(name){case "intent":case "geometry":return 4096;case "original.jpeg":return 10*1024*1024;case "crop.png":return 2*1024*1024;case "receipt":return 1024;case "failure":return 512;case "feature.bin":return 4096;case "feature-receipt":return 2048;default:throw new IllegalStateException("RECORD_NAME");}}
 private Set<String> names(File dir,boolean meta,boolean stages)throws Exception{
  guard();directory(dir,false);Root held=roots.get(dir.getPath());StructStat before=Os.fstat(held.fd);String[] list=dir.list();ObservedEnrollment.require(list!=null&&list.length<=(meta?4097:16),"INVENTORY_COUNT");Set<String> result=new TreeSet<>();
  for(String name:list){if(name.equals("owner.lock")&&meta)continue;boolean stage=name.endsWith(".new");String base=stage?name.substring(0,name.length()-4):name;int max=limit(base,meta);ObservedEnrollment.require(stages||!stage,"UNCONFIRMED_STAGE");File f=new File(dir,name);StructStat a=Os.lstat(f.getPath());java.io.FileDescriptor fd=Os.open(f.getPath(),OsConstants.O_RDONLY|OsConstants.O_NOFOLLOW|OsConstants.O_NONBLOCK,0);try{StructStat actual=Os.fstat(fd);regular(actual,max);ObservedEnrollment.require(identity(a).equals(identity(actual))&&identity(actual).equals(identity(Os.lstat(f.getPath()))),"INVENTORY_LEAF_CHANGED");}finally{Os.close(fd);}result.add(name);}
  String[] after=dir.list();held.verify();ObservedEnrollment.require(after!=null,"INVENTORY_CHANGED");EnrollmentIdentity.inventory(identity(before),identity(Os.fstat(held.fd)),identity(Os.lstat(dir.getPath())),new TreeSet<>(Arrays.asList(list)),new TreeSet<>(Arrays.asList(after)));guard();return result;
 }
 private byte[] read(File dir,String name,int max,boolean meta)throws Exception{return read(dir,name,max,meta,false);}
 private byte[] read(File dir,String name,int max,boolean meta,boolean allowEmpty)throws Exception{allowEmpty=EnrollmentReadBytes.scope(name,meta,allowEmpty);guard();int allowed=limit(name,meta);ObservedEnrollment.require(max>0&&max<=allowed,"READ_LIMIT");directory(dir,false);File f=new File(dir,name);StructStat before=Os.lstat(f.getPath());java.io.FileDescriptor fd=Os.open(f.getPath(),OsConstants.O_RDONLY|OsConstants.O_NOFOLLOW|OsConstants.O_NONBLOCK,0);try(FileInputStream in=new FileInputStream(fd)){StructStat s=Os.fstat(fd);regular(s,max);ObservedEnrollment.require(identity(before).equals(identity(s)),"READ_IDENTITY");byte[] bytes=EnrollmentReadBytes.read(in,s.st_size,max,allowEmpty);ObservedEnrollment.require(identity(s).equals(identity(Os.lstat(f.getPath())))&&identity(s).equals(identity(Os.fstat(fd))),"READ_CHANGED");directory(dir,false);guard();return bytes;}}
 private void publish(File dir,String name,byte[] bytes,boolean meta)throws Exception{guard();ObservedEnrollment.require(bytes!=null&&bytes.length>0&&bytes.length<=limit(name,meta),"PUBLISH_LIMIT");proofs.verify();long used=used();ObservedEnrollment.require(used<=ObservedEnrollment.CAP-bytes.length&&free()>=256L*1024*1024+bytes.length,"QUOTA");directory(dir,false);File target=new File(dir,name),stage=new File(dir,name+".new");try{Os.lstat(target.getPath());throw new IllegalStateException("NO_REPLACE");}catch(ErrnoException e){if(e.errno!=OsConstants.ENOENT)throw e;}java.io.FileDescriptor fd=Os.open(stage.getPath(),OsConstants.O_WRONLY|OsConstants.O_CREAT|OsConstants.O_EXCL|OsConstants.O_NOFOLLOW,0600);try(FileOutputStream out=new FileOutputStream(fd)){out.write(bytes);out.flush();out.getFD().sync();}directory(dir,false);guard();StructStat a=Os.fstat(roots.get(dir.getPath()).fd),f=Os.lstat(stage.getPath());regular(f,limit(name,meta));CameraProofRename.publish(dir.getPath(),stage.getName(),target.getName(),new long[]{a.st_dev,a.st_ino,f.st_dev,f.st_ino,f.st_size,f.st_mtim.tv_sec,f.st_mtim.tv_nsec,f.st_ctim.tv_sec,f.st_ctim.tv_nsec});ObservedEnrollment.require(Arrays.equals(bytes,read(dir,name,limit(name,meta),meta)),"PUBLISH_READBACK");}
 @Override public synchronized Set<String> names()throws Exception{proofs.verify();return names(ledger,true,true);}
 @Override public synchronized byte[] read(String name,int max)throws Exception{return read(ledger,name,max,true);}
 @Override public synchronized void publish(String name,byte[] bytes)throws Exception{publish(ledger,name,bytes,true);}
 private File recordRoot(int job){ObservedEnrollment.require(job>=1&&job<=64,"JOB_LIMIT");return new File(parent,String.format(Locale.ROOT,"observed-enrollment-record-%04d-v1",job));}
 public synchronized Record record(int job,boolean create)throws Exception{guard();File root=recordRoot(job);if(create)try{Os.lstat(root.getPath());throw new IllegalStateException("RECORD_CONSUMED");}catch(ErrnoException e){if(e.errno!=OsConstants.ENOENT)throw e;}directory(root,create);return new Record(root);}
 public final class Record implements local.cameracomponent.Evidence.Disk {
  private final File root;Record(File root){this.root=root;}
  public Set<String> allNames()throws Exception{synchronized(EnrollmentDisk.this){return EnrollmentDisk.this.names(root,false,false);}}
  @Override public Set<String> names()throws Exception{Set<String> names=allNames();names.remove("feature.bin");names.remove("feature-receipt");return names;}
  @Override public byte[] read(String n,int max)throws Exception{synchronized(EnrollmentDisk.this){return EnrollmentDisk.this.read(root,n,max,false);}}
  @Override public void publish(String n,byte[] bytes)throws Exception{synchronized(EnrollmentDisk.this){EnrollmentDisk.this.publish(root,n,bytes,false);}}
  @Override public long free(){return EnrollmentDisk.this.free();}
 }
 @Override public synchronized long used()throws Exception{guard();proofs.verify();long total=proofs.bytes();List<File> live=new ArrayList<>();live.add(ledger);for(int i=1;i<=64;i++){File dir=recordRoot(i);try{directory(dir,false);live.add(dir);}catch(ErrnoException e){if(e.errno!=OsConstants.ENOENT)throw e;}}
  for(File dir:live){Root held=roots.get(dir.getPath());StructStat before=Os.fstat(held.fd);Set<String> entries=names(dir,dir.equals(ledger),true);for(String n:entries){File f=new File(dir,n);StructStat a=Os.lstat(f.getPath());java.io.FileDescriptor fd=Os.open(f.getPath(),OsConstants.O_RDONLY|OsConstants.O_NOFOLLOW|OsConstants.O_NONBLOCK,0);try{StructStat actual=Os.fstat(fd);String base=n.endsWith(".new")?n.substring(0,n.length()-4):n;regular(actual,limit(base,dir.equals(ledger)));ObservedEnrollment.require(identity(a).equals(identity(actual))&&identity(actual).equals(identity(Os.lstat(f.getPath())))&&total<=ObservedEnrollment.CAP-actual.st_size,"QUOTA_OR_INVENTORY_CHANGED");total+=actual.st_size;}finally{Os.close(fd);}}held.verify();ObservedEnrollment.require(identity(before).equals(identity(Os.fstat(held.fd)))&&entries.equals(names(dir,dir.equals(ledger),true)),"INVENTORY_CHANGED");}guard();return accounting().total;}
 public synchronized byte[] readStage(String name)throws Exception{ObservedEnrollment.require(name.matches("event-[0-9]{4}"),"EVENT_NAME");return read(ledger,name+".new",EnrollmentStore.EVENT_BYTES,true,true);}
 public synchronized EnrollmentAccounting.Cut accounting()throws Exception{guard();proofs.verify();long[] charges=control.charges();return EnrollmentAccounting.scan(parent,charges[0],charges[1]);}
 @Override public long free(){return parent.getUsableSpace();}
 @Override public synchronized void close()throws Exception{if(closed)return;closed=true;Exception failure=null;try{lock.release();}catch(Exception e){failure=e;}try{lockStream.close();}catch(Exception e){if(failure==null)failure=e;else failure.addSuppressed(e);}for(Root root:roots.values())try{root.close();}catch(Exception e){if(failure==null)failure=e;else failure.addSuppressed(e);}try{parentHandle.close();}catch(Exception e){if(failure==null)failure=e;else failure.addSuppressed(e);}if(failure!=null)throw failure;}
}
